package com.booksyde.entity; import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID; @Entity @Table(name="comments",schema="public") public class CommentEntity {@Id private UUID id; @Column(name="manga_id") private UUID mangaId; @Column(name="volume_id") private UUID volumeId; @Column(name="user_id") private UUID userId; private String body; @Column(name="created_at",insertable=false,updatable=false) private OffsetDateTime createdAt; protected CommentEntity(){} public CommentEntity(UUID m,UUID v,UUID u,String b){id=UUID.randomUUID();mangaId=m;volumeId=v;userId=u;body=b;} public UUID getId(){return id;} public UUID getMangaId(){return mangaId;} public UUID getVolumeId(){return volumeId;} public UUID getUserId(){return userId;} public String getBody(){return body;} public OffsetDateTime getCreatedAt(){return createdAt;} public void setBody(String b){body=b;}}